def rle_decode(s):
    """Run-length decode a string: 'a3b2c1' -> 'aaabbc'."""
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        num = ''
        while i < len(s) and s[i].isdigit():
            num += s[i]
            i += 1
        out.append(ch * int(num))
    return ''.join(out)

def inc_digit_list(digits):
    """Add one to a non-negative integer represented as a digit list."""
    out = digits[:]
    for i in range(len(out) - 1, -1, -1):
        if out[i] < 9:
            out[i] += 1
            return out
        out[i] = 0
    return [1] + out

