def list_intersect(a, b):
    """Items present in both lists, in the order they appear in a (no repeats)."""
    in_b = set(b)
    seen = set()
    out = []
    for x in a:
        if x in in_b and x not in seen:
            seen.add(x)
            out.append(x)
    return out

