def run_encode(s):
    """Run-length encode a string: 'aaabbc' -> 'a3b2c1'."""
    if not s:
        return ''
    out = []
    run = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            run += 1
        else:
            out.append(s[i - 1] + str(run))
            run = 1
    out.append(s[-1] + str(run))
    return ''.join(out)

def expand_runs(s):
    """Run-length decode a string: 'a3b2c1' -> 'aaabbc'."""
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        num = ''
        while i < len(s) and s[i].isdigit():
            num += s[i]
            i += 1
        out.append(ch * int(num))
    return ''.join(out)

