def modal_value(xs):
    """Most frequent value in xs; ties broken by the smaller value."""
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    best = None
    best_n = 0
    for x in sorted(counts):
        if counts[x] > best_n:
            best = x
            best_n = counts[x]
    return best

def sum_divisors_eq(n):
    """True if n is a perfect number (sum of proper divisors equals n)."""
    if n < 2:
        return False
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
        i += 1
    return total == n

